import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Img,
} from '../remotionShim';


export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 8,
  popupImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/501504caea0940e4ac83403273d3f629.png",
  popScale = 1.1,
  tiltAngleX = 15,
  tiltAngleY = -25,
  extrusionLayers = 15,
  extrusionSpacing = 2.5,
  floatIntensity = 1.5,
  shadowOpacity = 0.6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const spr = spring({
    fps,
    frame,
    config: {
      damping: 14,
      stiffness: 90,
    },
  });

  const entranceZ = interpolate(spr, [0, 1], [-1500, 0]);
  const entranceRotX = interpolate(spr, [0, 1], [tiltAngleX + 60, tiltAngleX]);
  const entranceRotY = interpolate(spr, [0, 1], [tiltAngleY - 45, tiltAngleY]);
  const entranceOpacity = interpolate(spr, [0, 0.4], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const floatY = Math.sin(frame / 25) * 15 * floatIntensity;
  const floatRotX = Math.cos(frame / 30) * 2 * floatIntensity;
  const floatRotY = Math.sin(frame / 35) * 2 * floatIntensity;

  const finalZ = entranceZ;
  const finalRotX = entranceRotX + floatRotX;
  const finalRotY = entranceRotY + floatRotY;
  const finalScale = spr * popScale;

  const layers = Array.from({ length: extrusionLayers });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        perspective: "1500px",
        transition: "none",
      }}
    >
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          transformStyle: "preserve-3d",
          transform: `translateZ(${finalZ}px) rotateX(${finalRotX}deg) rotateY(${finalRotY}deg) translateY(${floatY}px) scale(${finalScale})`,
          opacity: entranceOpacity,
          transition: "none",
        }}
      >
        {layers.map((_, i) => {
          const depth = extrusionLayers - i;
          const isDeepest = i === 0;
          const isFront = i === extrusionLayers - 1;

          let filterStyle = "brightness(0.2)";
          if (isDeepest) {
            filterStyle = `brightness(0.15) drop-shadow(20px 40px 40px rgba(0,0,0,${shadowOpacity}))`;
          } else if (isFront) {
            filterStyle = "none";
          }

          return (
            <Img
              key={i}
              src={popupImage}
              style={{
                position: isFront ? "relative" : "absolute",
                maxWidth: width * 0.85,
                maxHeight: height * 0.7,
                objectFit: "contain",
                transform: `translateZ(-${depth * extrusionSpacing}px)`,
                filter: filterStyle,
                borderRadius: "24px",
                transition: "none",
              }}
            />
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ComponentName;